String scroll = "fireball";
String loud = scroll.toUpperCase();
System.out.println(scroll);  // fireball — unchanged
System.out.println(loud);    // FIREBALL — a new String

String a = new String("ice");
String b = new String("ice");
System.out.println(a == b);          // false — different objects
System.out.println(a.equals(b));     // true — same content
System.out.println(a.equalsIgnoreCase("ICE")); // true

